// Note: P07-P09 have been defined by the Orders/Observations Technical Committee as product experience messages.
type BAR_P06 struct {
	MSH     MSH               `hl7:"MSH,required"`
	EVN     EVN               `hl7:"EVN,required"`
	PATIENT []BAR_P06_PATIENT `hl7:"PATIENT,required"`
}

